/* ---------------- question sets ---------------- */
const SETS = [
 {id:"g1", lv:1, title:"What is it?", zh:"看图认一认", qs:[
  {pic:["horseshoe"], q:"What shape is this magnet?", o:["horseshoe (U-shaped)","bar (long and straight)","ring (with a hole)","button (flat disc)"], a:0,
   e:"A horseshoe magnet is bent into a U shape, so its two poles are close together.", z:"马蹄形（U 形）磁铁。"},
  {pic:["ringmagnets"], q:"These magnets have a hole in the middle. What are they called?", o:["ring magnets","bar magnets","horseshoe magnets","compasses"], a:0,
   e:"They are ring magnets. In the photo they float apart on the rod because like poles are facing each other, so they repel.", z:"环形磁铁。照片里同极相对，所以互相推开、浮起来。"},
  {pic:["compass"], q:"What is this used for?", o:["finding direction (North, South, East, West)","telling the time (hours, minutes, seconds)","measuring mass (grams and kilograms)","measuring temperature (degrees Celsius)"], a:0,
   e:"A compass has a magnetised needle that turns freely and points North–South.", z:"指南针用来辨别方向。"},
  {pic:["barfilings"], q:"Iron filings were sprinkled around a bar magnet. Where did most of the filings gather?", o:["at the two ends (the poles)","in the middle","evenly all over the magnet","nowhere — iron is not magnetic"], a:0,
   e:"The magnetic force is strongest at the poles, so most filings gather at the two ends.", z:"两极磁力最强，铁屑聚在两端。"},
  {pic:["tincan"], q:"A magnet attracts this food can. What is the can made of?", o:["steel with a thin coat of tin","tin with a thin coat of paint","aluminium with a coat of paint","copper with a thin coat of tin"], a:0,
   e:"Food \"tin\" cans are steel with a thin coat of tin. Steel is a magnetic material; tin, aluminium and copper are not.", z:"罐头罐是镀锡的钢，钢会被磁铁吸；锡、铝、铜都不会。"},
  {pic:["drinkcan"], q:"Most soft-drink cans are made of aluminium. Will a magnet attract this can?", o:["No — aluminium is not a magnetic material.","Yes — all metals are attracted by magnets.","Yes — shiny metal cans are attracted by magnets.","No — it is too light for a magnet to pull it."], a:0,
   e:"Aluminium is a metal, but it is not magnetic. Lightness and shininess have nothing to do with it.", z:"铝是金属，但不是磁性材料。"},
  {pic:["copperwire"], q:"A magnet is brought near this copper wire. What happens?", o:["Nothing — copper is not a magnetic material.","It is attracted — copper is a magnetic metal.","It is repelled — copper and the magnet push apart.","It becomes a magnet — the magnet magnetises it."], a:0,
   e:"Copper is a metal, but it is not magnetic. Do not mix it up with cobalt.", z:"铜不是磁性材料（钴才是）。"},
  {pic:["emagnet"], q:"This nail has a coil of wire around it, joined to a battery. What is it?", o:["an electromagnet","a compass","a bar magnet","a horseshoe magnet"], a:0,
   e:"Electric current flowing through the coil turns the nail into a magnet — an electromagnet.", z:"铁钉绕线圈接电池 = 电磁铁。"},
  {pic:["fridgeletters"], q:"These magnetic letters stick to the fridge door. What does this tell us about the door?", o:["It contains a magnetic material, such as steel.","It is made of aluminium, which magnets attract.","It is made of plastic, so the letters can stick.","It is a magnet that repels the magnetic letters."], a:0,
   e:"The magnets are attracted to the door, so the door must contain a magnetic material (the fridge body is steel).", z:"能吸住，说明门里有磁性材料（钢）。"},
  {pic:["nickelcube"], q:"This metal is nickel. Is nickel a magnetic material?", o:["Yes — iron, steel, nickel and cobalt are magnetic.","No — only iron and steel are magnetic materials.","No — nickel is like copper, which is not magnetic.","Yes — it is shiny, and all shiny metals are magnetic."], a:0,
   e:"The four magnetic materials to remember: iron, steel, nickel and cobalt.", z:"四种磁性材料：铁、钢、镍、钴。"}
 ]},
 {id:"g2", lv:2, title:"Magnetic or not?", zh:"磁性材料和易错点", qs:[
  {q:"Which materials are magnetic?", st:["iron","steel","nickel","copper"], o:["A and B only","A, B and C only","B, C and D only","A, B, C and D"], a:1,
   e:"Copper is not magnetic. Iron, steel, nickel (and cobalt) are.", z:"铜不是磁性材料。"},
  {q:"Which metal is NOT a magnetic material?", o:["aluminium","iron","cobalt","nickel"], a:0,
   e:"Aluminium is a metal, but a magnet does not attract it.", z:"铝不会被磁铁吸。"},
  {q:"Ming says, \"All metals are attracted by magnets.\" Which object shows that he is wrong?", o:["a copper wire","an iron nail","a steel paper clip","a nickel bar"], a:0,
   e:"Copper is a metal that is not attracted, so not all metals are magnetic.", z:"铜是金属，但不会被吸。"},
  {q:"Cobalt and copper sound alike. Which is correct?", o:["Cobalt is magnetic; copper is not.","Copper is magnetic; cobalt is not.","Both are magnetic.","Neither is magnetic."], a:0,
   e:"Cobalt (钴) is one of the four magnetic materials. Copper (铜) is not magnetic.", z:"钴有磁性，铜没有。"},
  {q:"Which objects will be attracted by a magnet?", st:["a steel paper clip","a gold ring","an iron nail","a glass marble"], o:["A and B only","A and C only","B and D only","A, C and D only"], a:1,
   e:"Steel and iron are magnetic. Gold is a non-magnetic metal; glass is a non-metal.", z:"钢和铁会被吸；金和玻璃不会。"},
  {q:"Which of these materials are NOT attracted by magnets?", st:["wood","plastic","rubber","steel"], o:["A and B only","A, B and C only","C and D only","A, B, C and D"], a:1,
   e:"Wood, plastic and rubber are not magnetic. Steel is magnetic.", z:"木、塑料、橡胶不会被吸；钢会。"},
  {q:"A can of baked beans is attracted by a magnet. Why?", o:["The can is made of steel with a thin coat of tin.","The can is made of tin, which is a magnetic material.","All cans are made of iron, which is a magnetic material.","The beans inside the can are a magnetic material."], a:0,
   e:"A \"tin\" can is mostly steel; the tin is only a thin coating. Tin itself is not magnetic, and aluminium drink cans are not attracted.", z:"罐头是镀锡的钢；锡本身没有磁性。"},
  {q:"A brass key and an iron key look the same. How can you tell which one is the iron key?", o:["Bring a magnet near: only the iron key is attracted.","See which one is shinier: iron is always shinier.","Put both in water: only the iron key will sink.","Weigh them: the iron key is always the heavier one."], a:0,
   e:"Iron is magnetic; brass is not. Both keys sink, and shine or weight does not tell us the material for sure.", z:"用磁铁试：铁会被吸，黄铜不会。"},
  {ch:"mtree", q:"Where would a steel paper clip, aluminium foil and a rubber band be placed?", o:["clip: A, foil: B, rubber band: C","clip: B, foil: A, rubber band: C","clip: A, foil: A, rubber band: C","clip: A, foil: C, rubber band: B"], a:0,
   e:"Steel is a metal attracted by a magnet (A). Aluminium is a metal that is not attracted (B). Rubber is a non-metal (C).", z:"钢 → A；铝 → B；橡胶 → C。"},
  {q:"At a recycling centre, a big magnet is moved over a pile of drink cans and food cans. Which cans are picked up?", o:["the steel cans","the aluminium cans","both the steel and aluminium cans","none of the cans"], a:0,
   e:"Only the steel cans are attracted. The aluminium cans are left behind, so the two metals are separated.", z:"磁铁只吸起钢罐，铝罐留下。"}
 ]},
 {id:"g3", lv:2, title:"Poles & compass", zh:"磁极和指南针", qs:[
  {q:"Where is the magnetic force of a bar magnet the strongest?", o:["at both poles (the two ends)","in the middle of the magnet","at the N pole, not the S pole","evenly along the whole magnet"], a:0,
   e:"The magnetic force is strongest at the poles. Both poles are equally able to attract magnetic materials.", z:"两极磁力最强。"},
  {ch:"clipsbar", q:"Paper clips were attracted to a bar magnet as shown. What does this show?", o:["The magnetic force is strongest at the poles.","The middle of the magnet has lost its magnetism.","Only the N pole of a magnet attracts paper clips.","The paper clips in the middle are not magnetic."], a:0,
   e:"Most clips hang from the two ends (poles); very few stick to the middle.", z:"回形针都挂在两端：两极磁力最强。"},
  {q:"The N pole of a magnet is brought near the N pole of another magnet. What happens?", o:["They repel (push each other away).","They attract (pull towards each other).","Nothing happens (neither one moves).","Both of them lose their magnetism."], a:0,
   e:"Like poles repel.", z:"同极相斥。"},
  {q:"Which pairs of poles attract each other?", st:["N and S","N and N","S and S","S and N"], o:["A only","A and D only","B and C only","A, B, C and D"], a:1,
   e:"Unlike poles (N and S) attract. Like poles (N and N, S and S) repel.", z:"异极相吸：N 和 S。"},
  {q:"A bar magnet is hung from a thread so that it can turn freely. When it stops moving, it ___.", o:["points North–South","points East–West","points towards the nearest wall","points in a different direction each time"], a:0,
   e:"A freely suspended magnet always comes to rest pointing North–South, with its N pole pointing North.", z:"自由悬挂的磁铁停在南北方向。"},
  {q:"The needle of a compass is ___.", o:["a small magnet","a piece of copper","a piece of plastic","a piece of glass"], a:0,
   e:"The compass needle is a tiny magnet that turns freely to point North–South.", z:"指南针的针是一块小磁铁。"},
  {q:"Rod X is brought near the N pole of a magnet, and X is attracted. Which is correct?", o:["X could be a magnet or a magnetic material.","X must be a magnet.","X must be a magnetic material, not a magnet.","X must be made of aluminium."], a:0,
   e:"A magnet attracts magnetic materials AND the unlike pole of another magnet. Attraction alone cannot tell us which.", z:"被吸住：可能是磁铁，也可能只是磁性材料。"},
  {q:"Which observation PROVES that rod Y is a magnet?", o:["One end of Y repels the N pole of a magnet.","Y is attracted by the S pole of a magnet.","Y is made of steel, a magnetic material.","Y is shiny and heavy, like most magnets."], a:0,
   e:"Only magnets repel each other. Being attracted, or being made of steel, does not prove Y is a magnet.", z:"能相斥的才一定是磁铁。"},
  {ch:"rings", q:"Ring Q floats above ring R. Why?", o:["The facing sides of Q and R are like poles, so they repel.","The facing sides of Q and R are unlike poles, so they attract.","Q is much lighter than R, so Q does not slide down.","Q is stuck to the pencil, so Q cannot slide down."], a:0,
   e:"Like poles repel, so Q is pushed up and floats above R.", z:"Q 和 R 相对的面是同极，互相排斥。"},
  {q:"A bar magnet breaks into two pieces. Which is correct?", o:["Each piece is a magnet with an N pole and an S pole.","One piece is only N, and the other piece is only S.","Both pieces lose all of their magnetism at once.","Only the bigger piece is still a magnet after it breaks."], a:0,
   e:"Every magnet has two poles. Each broken piece becomes a smaller magnet with its own N and S poles.", z:"断开后每一段都有 N 极和 S 极。"}
 ]},
 {id:"g4", lv:3, title:"Experiments", zh:"实验题", qs:[
  {ch:"clipsbars", q:"Which magnet is the strongest?", o:["P","Q","R","S"], a:1, fix:true,
   e:"Magnet Q attracted the most paper clips (15).", z:"吸的回形针最多的最强：Q。"},
  {ch:"clipsbars", q:"Which statements are correct?", st:["Magnet Q is the strongest.","Magnet R is the weakest.","Magnet Q must be the biggest magnet."], o:["A only","A and B only","B and C only","A, B and C"], a:1,
   e:"The graph shows strength, not size. A small magnet can be stronger than a big one, so C cannot be concluded.", z:"图只显示强弱，不能说明大小。"},
  {ch:"clipsbars", q:"To make it a fair test, which must be kept the same?", st:["the type and size of the paper clips","the magnet being tested","how the paper clips are hung from the magnet"], o:["A only","A and C only","B and C only","A, B and C"], a:1,
   e:"The magnet is the ONE thing being changed. The clips and how they are hung must be the same.", z:"只改变磁铁；回形针和挂法要一样。"},
  {ch:"magdist", q:"Which magnet is the strongest?", o:["W","X","Y","Z"], a:1, fix:true,
   e:"Magnet X attracted the pin from the furthest distance (7 cm), so its magnetic force reaches the furthest.", z:"隔得越远还能吸，磁铁越强：X。"},
  {ch:"sheets", q:"Based on the results, what happens as the number of cardboard sheets increases?", o:["Fewer paper clips are attracted.","More paper clips are attracted.","The number of paper clips stays the same.","The magnet becomes a stronger magnet."], a:0,
   e:"12 → 9 → 6 → 3: the more sheets, the fewer clips attracted.", z:"纸板越多，吸的回形针越少。"},
  {ch:"sheets", q:"What does Mei's experiment show?", o:["Magnetic force can pass through cardboard, but it is weaker through more sheets.","Magnetic force can pass through cardboard, and it is stronger through more sheets.","Magnetic force cannot pass through cardboard, so fewer clips are attracted.","The magnet itself becomes weaker each time a cardboard sheet is added."], a:0,
   e:"Clips were still attracted through 6 sheets, so the force passes through cardboard, but fewer clips were attracted as sheets were added. The magnet itself did not change — the force reaching the clips got weaker.", z:"磁力能穿过纸板，但越厚越弱。磁铁本身没有变弱。"},
  {ch:"emag", q:"Which two set-ups should be compared to find out if the NUMBER OF COILS affects the strength of an electromagnet?", o:["A and B","A and C","B and D","A and D"], a:0, fix:true,
   e:"A and B have the same number of batteries; only the number of coils is different. (C and D would also work.)", z:"A 和 B 只有线圈数不同。"},
  {ch:"emag", q:"Which conclusions are correct?", st:["More coils of wire made the electromagnet stronger.","More batteries made the electromagnet stronger.","The number of batteries did not affect the strength."], o:["A only","A and B only","B and C only","A, B and C"], a:1,
   e:"A → B (more coils): 4 → 8 clips. A → D (more batteries): 4 → 7 clips. Both made it stronger, so C is wrong.", z:"线圈多、电池多都让电磁铁更强。"},
  {ch:"bars3", q:"Which bar is a magnet?", o:["K only","J and K only","J only","L only"], a:0,
   e:"One end of K was repelled, so K is a magnet. J was attracted at both ends, so J is a magnetic material but not a magnet. L is not magnetic.", z:"只有 K 有一端被排斥，所以 K 是磁铁。"},
  {ch:"bars3", q:"Bar L could be made of ___.", o:["aluminium","iron","steel","nickel"], a:0,
   e:"L was not attracted at all, so it is not a magnetic material. Iron, steel and nickel are magnetic.", z:"L 完全没反应：铝。"}
 ]},
 {id:"g5", lv:3, title:"Making & using magnets", zh:"制造和使用磁铁", qs:[
  {ch:"stroke", q:"Jun stroked steel bar AB with the N pole of a magnet, from A to B, many times. Which pole will end B become?", o:["S pole","N pole","no pole — steel cannot become a magnet","both N and S"], a:0,
   e:"The end where the strokes finish becomes the opposite pole to the stroking pole. Stroking with an N pole makes end B an S pole.", z:"用 N 极摩擦，结束端 B 变成 S 极。"},
  {ch:"stroke", q:"Which is the correct way to use the stroke method?", o:["Stroke one way with the same pole, lifting the magnet high each time.","Rub the magnet quickly back and forth along the bar, many times.","Stroke in one direction, using the N pole and then the S pole in turns.","Tap the bar hard with one pole of the magnet, many times over."], a:0,
   e:"Same pole, same direction, lift high, many times. Back-and-forth or changing poles undoes the magnetism.", z:"同一个极、同一个方向、抬高再回来。"},
  {q:"Which object can be made into a magnet by the stroke method?", o:["an iron nail","a copper wire","an aluminium rod","a plastic ruler"], a:0,
   e:"Only magnetic materials can be magnetised. Iron is magnetic; copper, aluminium and plastic are not.", z:"只有磁性材料能被磁化。"},
  {q:"Ken stroked a steel needle 10 times, and it picked up 2 pins. He stroked an identical needle 40 times in the same way. What will most likely happen?", o:["It will pick up more pins.","It will pick up fewer pins.","It will not pick up any pins.","It will repel the pins."], a:0,
   e:"More strokes make a stronger magnet (up to a limit). Steel pins are not magnets, so they cannot be repelled.", z:"摩擦次数越多，磁性越强。"},
  {ch:"electro", q:"When the switch is closed, the iron nail attracts paper clips. What happens when the switch is opened?", o:["The nail loses its magnetism, and the clips drop off.","The clips stay on, because the nail is now a strong magnet.","The nail repels the clips.","The battery attracts the clips."], a:0,
   e:"With no current in the coil, the iron nail loses its magnetism.", z:"断电，电磁铁失去磁性，回形针掉下来。"},
  {ch:"electro", q:"Which changes will make this electromagnet stronger?", st:["Wind more coils of wire around the nail.","Use more batteries.","Replace the iron nail with a wooden stick."], o:["A only","A and B only","B and C only","A, B and C"], a:1,
   e:"More coils and more batteries make it stronger. Wood is not magnetic, so a wooden stick makes it much weaker.", z:"多绕线圈、多加电池；换成木棒会变弱。"},
  {pic:["cranemagnet"], q:"Cranes that lift steel often use electromagnets instead of ordinary magnets. Why?", o:["An electromagnet can be switched off to drop the steel.","An electromagnet can also lift aluminium and copper.","An electromagnet works without needing any electricity.","An electromagnet is always much lighter than a magnet."], a:0,
   e:"Switching off the current lets the crane drop the steel exactly where it is needed.", z:"电磁铁可以断电，把钢放下来。"},
  {q:"Which actions can make a magnet lose its magnetism?", st:["dropping it many times","heating it strongly","hammering it","keeping it in a cool, dry drawer"], o:["A and B only","A, B and C only","B, C and D only","A, B, C and D"], a:1,
   e:"Dropping, heating strongly and hammering can make a magnet weaker. Keeping it in a cool, dry drawer does not.", z:"掉落、加热、敲打会让磁铁失去磁性。"},
  {q:"A fridge door has a magnetic strip inside its rubber seal. Why?", o:["It is attracted to the steel body, so the door shuts tightly and cold air stays in.","It repels the steel body of the fridge, so the door can be opened more easily.","It is attracted to the rubber seal, so the rubber seal does not fall off the door.","Its magnetic force makes the air inside the fridge colder and keeps food fresh."], a:0,
   e:"The magnetic strip pulls the door against the steel body, so there is no gap for cold air to escape.", z:"磁条吸住冰箱的钢身，门关得紧，冷气不会跑出来。"},
  {q:"A magnet can attract a steel paper clip through which of these?", st:["a sheet of paper","a glass of water","a thin plastic tray","a piece of cloth"], o:["A and B only","A, C and D only","B, C and D only","A, B, C and D"], a:3,
   e:"Magnetic force can act through non-magnetic materials such as paper, glass, water, plastic and cloth.", z:"磁力能穿过纸、玻璃、水、塑料和布。"}
 ]},
 {id:"g6", lv:4, title:"Full-mark answers", zh:"选出能拿满分的答案", qs:[
  {q:"Fiona says, \"A magnet attracts all metals.\" Explain why she is wrong. [1 mark]\nWhich answer gets the mark?", o:["Some metals, such as aluminium and copper, are not attracted by a magnet.","Some metals, such as aluminium and copper, will not stick to a magnet at all.","Some metals, such as nickel and cobalt, are not attracted by a magnet.","Some metals, such as nickel and cobalt, will not stick to a magnet at all."], a:0,
   n:["✓ Names metals that are NOT attracted, with the keyword \"attracted\".","½ Right metals, but \"stick to\" is an everyday word. Write \"are not attracted by\".","✗ Nickel and cobalt ARE magnetic materials (cobalt is not copper!).","✗ Wrong metals (nickel and cobalt are magnetic) and an everyday word (\"stick\")."],
   e:"To show that she is wrong, name metals that a magnet does NOT attract (aluminium, copper), and use the keyword \"attracted\".", z:"举出不会被吸的金属（铝、铜），用关键词 attracted，不要写 stick。"},
  {q:"Rod X is attracted to the N pole of a magnet. Tim says, \"X is a magnet.\" Is he right? Explain. [2 marks]", o:["Not necessarily. X could be just iron or steel, because magnetic materials are attracted too.","Yes. X was attracted to the N pole, so the end of X facing the magnet must be an S pole.","No. X is only a magnetic material, because a magnet attracts magnetic materials such as iron.","Not necessarily. X could be a magnet, or it could be a magnetic material such as aluminium."], a:0,
   n:["✓ We cannot be sure (1) + why: magnetic materials are attracted too (1) — 2 marks.","✗ Attraction does not prove that X is a magnet — a plain iron bar is attracted too.","½ Too sure: X might also be a magnet. Attraction alone cannot tell us which — 1 mark.","½ Right idea, but aluminium is not a magnetic material, so it would not be attracted — 1 mark."],
   e:"Attraction: X is a magnet OR a magnetic material. Only repulsion proves that X is a magnet.", z:"相吸不能证明是磁铁（可能只是铁或钢）；相斥才能证明。"},
  {ch:"clipsbars", q:"Which magnet is the strongest? Explain using the results. [2 marks]", o:["Q. It attracted the most paper clips, 15, so its magnetic force is the strongest.","Q. It looks like the biggest magnet, so its magnetic force must be the strongest.","R. It attracted the fewest paper clips, 3, so its magnetic force is the strongest.","Q. It attracted more paper clips than magnet P, so it is the strongest magnet."], a:0,
   n:["✓ Right magnet + evidence from the results (the MOST paper clips) — 2 marks.","½ Right magnet, but the results do not show size, and size does not decide strength — 1 mark.","✗ The fewest paper clips means the WEAKEST magnet.","½ Right magnet, but compare it with ALL the magnets: it attracted the most — 1 mark."],
   e:"Use the data: the magnet that attracted the MOST paper clips (compared with all the others) is the strongest.", z:"用数据：吸的回形针最多 = 最强，要和所有磁铁比。"},
  {ch:"electro", q:"Explain how the iron nail becomes a magnet. [1 mark]", o:["When the switch is closed, electric current flows through the coil and magnetises the nail.","When the switch is closed, magnetism flows out of the battery, along the wire, into the nail.","When the switch is closed, the iron nail becomes a magnet and attracts the paper clips.","When the switch is opened, no current flows, and the iron nail becomes a magnet."], a:0,
   n:["✓ Keywords: switch closed, electric current, coil, magnetised.","✗ A battery is not a magnet. It makes an electric current flow.","½ Says what happens, not how: an electric current must flow through the coil.","✗ The wrong way round: with the switch open, no current flows, so the nail is NOT a magnet."],
   e:"Keywords: switch closed → electric current flows through the coil → the iron nail is magnetised.", z:"关键词：开关闭合、电流流过线圈、铁钉被磁化。"},
  {pic:["cranemagnet"], q:"Why is an electromagnet better than an ordinary magnet for a crane that lifts steel? [1 mark]", o:["It can be switched off, so the crane can drop the steel where it is needed.","It can be switched on and off, which makes it a very useful kind of magnet.","It is always stronger, so the crane can lift heavier steel than any magnet can.","It can attract aluminium as well as steel, so the crane can lift any kind of metal."], a:0,
   n:["✓ The advantage (it can be switched off) + how it helps the crane (it drops the steel).","½ The advantage, but not linked to the job: say that it lets the crane drop the steel.","✗ \"Always\" is wrong: an electromagnet is not always stronger than a magnet.","✗ Aluminium is not a magnetic material, so it cannot lift every kind of metal."],
   e:"Give the advantage AND link it to the job: switch off the current → the steel drops where it is needed.", z:"写优点，也要写它怎样帮助起重机：断电就能把钢放下。"},
  {ch:"sheets", q:"What can Mei conclude from her experiment? [1 mark]", o:["As the number of cardboard sheets increases, the number of paper clips attracted decreases.","As the number of cardboard sheets increases, the number of paper clips attracted increases.","The number of paper clips attracted went down from 12 to 9, then to 6 and then to 3.","Cardboard blocks magnetic force, so no paper clips are attracted through the cardboard."], a:0,
   n:["✓ Links what was changed (sheets) to what was measured (paper clips).","✗ The opposite of the results.","½ Only describes the results. A conclusion links them to the number of sheets.","✗ Paper clips were still attracted through 6 sheets."],
   e:"A conclusion links the changed variable to the result: \"As ___ increases, ___ decreases.\"", z:"结论句：随着……增加，……减少。只抄数据不算结论。"},
  {ch:"stroke", q:"Jun wants his steel bar to become a stronger magnet using the stroke method. What should he do? [1 mark]", o:["Stroke it more times, in one direction, with the same pole of the magnet.","Stroke it more times, moving the magnet back and forth along the whole bar.","Stroke it more times, using the N pole and the S pole of the magnet in turns.","Stroke it more times, after heating the steel bar strongly over a flame."], a:0,
   n:["✓ More strokes, done the correct way (one direction, same pole).","✗ Back-and-forth strokes do not make a good magnet.","✗ Changing poles undoes the magnetism.","✗ Heating weakens magnets."],
   e:"More strokes give a stronger magnet, but only if every stroke uses the same pole in the same direction.", z:"同一方向、同一个极，多摩擦几次。"},
  {ch:"rings", q:"Explain why ring Q floats above ring R. [1 mark]", o:["The faces of Q and R facing each other are like poles, so they repel each other.","Q and R repel each other, so ring Q is pushed up and stays above ring R.","The faces of Q and R facing each other are unlike poles, so they repel each other.","Ring Q is lighter than ring R, so ring Q stays higher up on the pencil."], a:0,
   n:["✓ The reason (like poles face each other) + the result (they repel).","½ Says what happens, but not why: the faces facing each other are like poles.","✗ Unlike poles attract — they do not repel.","✗ Weight is not the reason. Q floats because like poles repel."],
   e:"Give the reason (like poles face each other) and the result (they repel).", z:"写原因（相对的面是同极）和结果（互相排斥）。"},
  {ch:"rings", q:"Ring Q is turned upside down and put back on the pencil. What will happen? [1 mark]", o:["Q will rest on R, and P will float above Q.","Q will float above R, and P will rest on Q.","Q will rest on R, and P will rest on Q.","Q will float above R, and P will float above Q."], a:0,
   n:["✓ Turning Q over swaps its poles: Q and R now attract, while P and Q now repel.","✗ That is how the rings were before. Turning Q over swaps both of its faces.","✗ Q's top face has changed too: P and Q now have like poles facing, so P floats.","✗ Q and R now have unlike poles facing, so they attract — Q drops onto R."],
   e:"Turning Q over swaps the poles that face its neighbours: below it, unlike poles now attract; above it, like poles now repel.", z:"把 Q 翻过来，它上下两面的极都对调了：和 R 相吸，和 P 相斥。"},
  {q:"Suggest why a compass should be kept away from magnets. [1 mark]", o:["The needle is a magnet. A nearby magnet attracts or repels it, so it will not point North–South.","A nearby magnet makes the needle lose all of its magnetism, so the compass can never work again.","The needle is made of copper, so a nearby magnet pulls it to point in the wrong direction.","A nearby magnet will make the compass needle turn round and point in the wrong direction."], a:0,
   n:["✓ Says what the needle is (a magnet) and what goes wrong (it does not point North–South).","✗ Over-statement: the needle is pulled or pushed; it does not lose all its magnetism.","✗ A compass needle is a magnet. Copper is not magnetic, so a magnet would not move it.","½ Says what goes wrong, but not why: the needle is a magnet, so it is attracted or repelled."],
   e:"Say what the needle is (a tiny magnet) and what goes wrong (it is attracted or repelled, so it does not point North–South).", z:"指南针的针是磁铁，会被吸或被排斥，就不能指南北。"}
 ]}
];

